/* === 1. IN-GAME ENGINE & HUD STYLES (v5.50.0) === */
  /* ========================================================================== */
  /* MOBILE RESPONSIVE STYLES & TOUCH CONTROLS (v4.83.0) */
  /* ========================================================================== */
  * {
    -webkit-tap-highlight-color: transparent;
    user-select: none;
    -webkit-user-select: none;
  }
  
  /* Touch Action and Viewport */
  body, html {
    touch-action: manipulation;
    overflow: hidden;
    position: fixed;
    width: 100%;
    height: 100%;
  }

  /* Mobile Responsive HUD Overrides */
  @media (max-width: 900px), (max-height: 600px) {
    #hud-quick-controls {
      display: none !important;
    }
    .hud-desktop-only {
      display: none !important;
    }
    .modal-overlay {
      padding: 0.5rem !important;
    }
    .modal-overlay .nms-panel {
      max-width: 98vw !important;
      max-height: 88vh !important;
      padding: 0.75rem !important;
      font-size: 11px !important;
    }
    #top-left-status {
      transform: scale(0.85);
      transform-origin: top left;
    }
    #top-right-status {
      transform: scale(0.85);
      transform-origin: top right;
    }
  }

  /* Mobile Virtual Controls Overlay */
  #mobile-touch-layer {
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 40;
    display: none; /* dynamically displayed on touch or mobile toggle */
  }

  .touch-interactive {
    pointer-events: auto;
    touch-action: none;
  }

  /* Virtual Joystick */
  #mobile-joystick-zone {
    position: absolute;
    bottom: 24px;
    left: 20px;
    width: 130px;
    height: 130px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(15, 23, 42, 0.6) 0%, rgba(6, 182, 212, 0.15) 100%);
    border: 2px solid rgba(6, 182, 212, 0.45);
    box-shadow: 0 0 20px rgba(6, 182, 212, 0.25), inset 0 0 15px rgba(6, 182, 212, 0.15);
    display: flex;
    align-items: center;
    justify-content: center;
  }

  #mobile-joystick-knob {
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: radial-gradient(circle, #38bdf8 0%, #0284c7 100%);
    border: 2px solid #e0f2fe;
    box-shadow: 0 0 14px rgba(56, 189, 248, 0.8);
    position: absolute;
    pointer-events: none;
    transition: transform 0.05s ease-out;
  }

  /* Action Buttons Cluster */
  #mobile-actions-cluster {
    position: absolute;
    bottom: 24px;
    right: 18px;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 10px;
  }

  .mobile-touch-btn {
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: monospace;
    font-weight: bold;
    user-select: none;
    cursor: pointer;
    box-shadow: 0 4px 15px rgba(0,0,0,0.5);
    transition: transform 0.08s ease, filter 0.08s ease;
    border-width: 2px;
  }

  .mobile-touch-btn:active {
    transform: scale(0.92);
    filter: brightness(1.25);
  }

  /* Mobile Command Wheel Sheet */
  #mobile-command-sheet {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background: rgba(10, 15, 29, 0.96);
    border-top: 2px solid #06b6d4;
    box-shadow: 0 -10px 40px rgba(6, 182, 212, 0.3);
    border-radius: 16px 16px 0 0;
    padding: 16px;
    z-index: 50;
    display: none;
    max-height: 70vh;
    overflow-y: auto;
    font-family: monospace;
  }
  
   
