  /* ========================================================================== */
  /* COMPLETE OFFLINE NMS SCI-FI UI & BUTTON SYSTEM (ZERO-DEPENDENCY v5.50.1) */
  /* ========================================================================== */
  .hidden { display: none !important; }

  /* Universal Sci-Fi Button Reset */
  button {
    box-sizing: border-box !important;
    font-family: 'Rajdhani', ui-monospace, SFMono-Regular, monospace !important;
    cursor: pointer !important;
    border-style: solid !important;
    border-width: 1px !important;
    border-radius: 4px !important;
    padding: 6px 12px !important;
    outline: none !important;
    transition: all 0.15s ease !important;
    background: rgba(15, 23, 42, 0.9);
    border-color: rgba(100, 116, 139, 0.4);
    color: #e2e8f0;
    line-height: 1.25 !important;
  }

  /* Close Buttons [X] */
  button[onclick*="close"], button[onclick*="Close"] {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    color: #9ca3af !important;
    padding: 4px 10px !important;
    font-size: 20px !important;
    line-height: 1 !important;
  }
  button[onclick*="close"]:hover, button[onclick*="Close"]:hover {
    color: #ffffff !important;
    background: rgba(255, 255, 255, 0.12) !important;
    border-radius: 4px !important;
    box-shadow: none !important;
    transform: none !important;
  }

  /* Gradient Button Themes */
  [class*="from-orange"], button[class*="from-orange"] {
    background: linear-gradient(135deg, #ea580c 0%, #b45309 100%) !important;
    color: #ffffff !important;
    border: 1px solid #f97316 !important;
    box-shadow: 0 0 14px rgba(249, 115, 22, 0.4) !important;
  }
  [class*="from-yellow"], [class*="from-amber"], button[class*="from-yellow"], button[class*="from-amber"] {
    background: linear-gradient(135deg, #d97706 0%, #a16207 100%) !important;
    color: #ffffff !important;
    border: 1px solid #facc15 !important;
    box-shadow: 0 0 14px rgba(234, 179, 8, 0.4) !important;
  }
  [class*="from-emerald"], [class*="from-green"], [class*="from-teal"], button[class*="from-emerald"], button[class*="from-green"], button[class*="from-teal"] {
    background: linear-gradient(135deg, #059669 0%, #0f766e 100%) !important;
    color: #ffffff !important;
    border: 1px solid #10b981 !important;
